import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The gradient wiping across the word, the giant word drifting left, and the
// cut to the compact word settling in place. Frames on the 30 fps scene
// timeline, after `speed`. The ids are public: a saved `timing` prop refers
// to them.

type GradientScaleCutTextElementId = "reveal" | "giant" | "compact";

interface GradientScaleCutTextTimingProps {
  /** Frame the giant word cuts to the compact one. */
  cutFrame?: number;
}

const CUT_FRAME = 13;
/** The gradient finishes its wipe on this frame. */
const REVEAL_END = 33;
/** The compact word sheds its blur over `SETTLE_FRAMES` after the cut. */
const SETTLE_FRAMES = 8;
/** Its slide holds a frame, then eases through these keys from the cut. */
const MOVE_AT = 1;
const MOVE_MID = 2;
const MOVE_LATE = 4;

// The giant word travels until the frame before the cut; the compact word
// follows it, so stretching the giant word moves the cut.
const gradientScaleCutTextTimeline = defineTimeline<
  GradientScaleCutTextElementId,
  GradientScaleCutTextTimingProps
>(
  ({
    cutFrame = CUT_FRAME,
  }): TimelineElement<GradientScaleCutTextElementId>[] => {
    const safeCutFrame = Math.max(cutFrame, 1);
    return [
      {
        id: "reveal",
        lane: "Gradient",
        label: "gradient wipe",
        start: 0,
        length: REVEAL_END,
      },
      {
        id: "giant",
        lane: "Word",
        label: "giant word",
        start: 0,
        length: Math.max(safeCutFrame - 1, 1),
      },
      {
        id: "compact",
        lane: "Word",
        label: "compact word",
        start: safeCutFrame,
        length: SETTLE_FRAMES,
        follows: "giant",
        beats: { moveAt: MOVE_AT, moveMid: MOVE_MID, moveLate: MOVE_LATE },
      },
    ];
  },
);

interface GradientScaleCutTextProps {
  text?: string;
  giantFontSize?: number;
  compactFontSize?: number;
  fontWeight?: number;
  gradientStart?: string;
  gradientEnd?: string;
  ghostColor?: string;
  backgroundColor?: string;
  anchorOffsetX?: number;
  giantTravel?: number;
  settleTravel?: number;
  cutFrame?: number;
  revealSoftness?: number;
  compactBlur?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches the gradient wipe, the giant word and the
   * compact word, by the ids in `./timeline`. Frames on the scene timeline,
   * after `speed`.
   */
  timing?: Timing<GradientScaleCutTextElementId>;
}

const gradientScaleCutTextLength = 36;

const GIANT_Y = -28;
const GIANT_X_CORRECTION = -48;
const COMPACT_Y = 5;
const COMPACT_X_SCALE = 0.87;
const COMPACT_START_X_CORRECTION = 28;
const FONT_FAMILY = "Arial, Helvetica, sans-serif";
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

interface TextLayerProps {
  text: string;
  fontSize: number;
  fontWeight: number;
  gradientStart: string;
  gradientEnd: string;
  ghostColor: string;
  maskImage: string;
}

function TextLayer({
  text,
  fontSize,
  fontWeight,
  gradientStart,
  gradientEnd,
  ghostColor,
  maskImage,
}: TextLayerProps) {
  const textStyle = {
    display: "block",
    fontFamily: FONT_FAMILY,
    fontSize,
    fontWeight,
    letterSpacing: 0,
    lineHeight: 1.12,
    whiteSpace: "nowrap" as const,
  };

  return (
    <div style={{ position: "relative" }}>
      <span style={{ ...textStyle, color: ghostColor }}>{text}</span>
      <span
        style={{
          ...textStyle,
          position: "absolute",
          inset: 0,
          color: "transparent",
          backgroundImage: `linear-gradient(90deg, ${gradientStart} 0%, ${gradientStart} 4%, ${gradientEnd} 26%, ${gradientEnd} 100%)`,
          backgroundClip: "text",
          maskImage,
          maskRepeat: "no-repeat",
          opacity: 1,
          WebkitBackgroundClip: "text",
          WebkitMaskImage: maskImage,
          WebkitMaskRepeat: "no-repeat",
        }}
      >
        {text}
      </span>
    </div>
  );
}

function GradientScaleCutTextBase(props: GradientScaleCutTextProps) {
  const {
    text = "Introducing",
    giantFontSize = 520,
    compactFontSize = 132,
    fontWeight = 700,
    gradientStart = "#f04a14",
    gradientEnd = "#f3f1f1",
    ghostColor = "#170b0a",
    backgroundColor = "#000000",
    anchorOffsetX = -16,
    giantTravel = 400,
    settleTravel = 160,
    revealSoftness = 14,
    compactBlur = 12,
    speed = 1,
    className,
    timing,
  } = props;
  const frame = useSceneFrame() * Math.max(speed, 0);
  const { durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    gradientScaleCutTextTimeline,
    props,
    durationInFrames * Math.max(speed, 0),
    timing,
  );
  const reveal = tl.get("reveal");
  const giant = tl.get("giant");
  const compact = tl.get("compact");
  const cutAt = compact.start;
  const safeGiantFontSize = Math.max(giantFontSize, 1);
  const safeCompactFontSize = Math.max(compactFontSize, 1);
  const safeSoftness = Math.max(revealSoftness, 0);
  const safeBlur = Math.max(compactBlur, 0);
  const revealProgress = interpolate(
    frame,
    [reveal.start, reveal.end],
    [0.02, 1],
    {
      ...clamp,
      easing: Easing.bezier(0.22, 0.74, 0.24, 1),
    },
  );
  const revealEdge = revealProgress * (100 + safeSoftness / 2);
  const revealSolid = Math.max(0, revealEdge - safeSoftness / 2);
  const revealFade = revealEdge + safeSoftness / 2;
  const maskImage = `linear-gradient(90deg, #000 0%, #000 ${revealSolid}%, transparent ${revealFade}%, transparent ${revealFade}%)`;
  const giantProgress = interpolate(frame, [giant.start, giant.end], [0, 1], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
  const settleProgress = interpolate(
    frame,
    [compact.start, compact.end],
    [0, 1],
    {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    },
  );
  const moveProgress = interpolate(
    frame,
    [
      cutAt + compact.beat("moveAt"),
      cutAt + compact.beat("moveMid"),
      cutAt + compact.beat("moveLate"),
      compact.end,
    ],
    [0, 0.58, 0.875, 1],
    clamp,
  );
  const showGiant = frame < cutAt;
  const compactX =
    interpolate(moveProgress, [0, 1], [settleTravel, 0], clamp) +
    COMPACT_START_X_CORRECTION * (1 - moveProgress);
  const compactBlurValue = safeBlur * (1 - settleProgress);

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
      }}
    >
      {showGiant ? (
        <div
          style={{
            position: "absolute",
            top: `calc(50% + ${GIANT_Y}px)`,
            left: `calc(50% + ${anchorOffsetX + GIANT_X_CORRECTION - giantTravel * giantProgress}px)`,
            opacity: 1,
            transform: "translate3d(0, -50%, 0)",
          }}
        >
          <TextLayer
            text={text}
            fontSize={safeGiantFontSize}
            fontWeight={fontWeight}
            gradientStart={gradientStart}
            gradientEnd={gradientEnd}
            ghostColor={ghostColor}
            maskImage={maskImage}
          />
        </div>
      ) : (
        <div
          style={{
            position: "absolute",
            top: `calc(50% + ${COMPACT_Y}px)`,
            left: `calc(50% + ${anchorOffsetX + compactX}px)`,
            filter: `blur(${compactBlurValue}px)`,
            opacity: 1,
            transform: `translate3d(-50%, -50%, 0) scaleX(${COMPACT_X_SCALE})`,
            transformOrigin: "center",
          }}
        >
          <TextLayer
            text={text}
            fontSize={safeCompactFontSize}
            fontWeight={fontWeight}
            gradientStart={gradientStart}
            gradientEnd={gradientEnd}
            ghostColor={ghostColor}
            maskImage={maskImage}
          />
        </div>
      )}
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Introducing",
    description: "Text",
  },
  giantFontSize: {
    type: "number",
    min: 160,
    max: 720,
    step: 4,
    default: 520,
    description: "Giant font size",
    hiddenFromList: false,
  },
  compactFontSize: {
    type: "number",
    min: 40,
    max: 240,
    step: 2,
    default: 132,
    description: "Compact font size",
    hiddenFromList: false,
  },
  anchorOffsetX: {
    type: "number",
    min: -400,
    max: 400,
    step: 4,
    default: -16,
    description: "Final horizontal anchor offset",
    hiddenFromList: false,
  },
  giantTravel: {
    type: "number",
    min: 0,
    max: 800,
    step: 4,
    default: 400,
    description: "Giant phase left travel",
    hiddenFromList: false,
  },
  settleTravel: {
    type: "number",
    min: 0,
    max: 400,
    step: 4,
    default: 160,
    description: "Compact entrance travel",
    hiddenFromList: false,
  },
  cutFrame: {
    type: "number",
    min: 4,
    max: 24,
    step: 1,
    default: 13,
    description: "Hard cut frame",
    hiddenFromList: false,
  },
  revealSoftness: {
    type: "number",
    min: 0,
    max: 40,
    step: 1,
    default: 14,
    description: "Reveal edge softness",
    hiddenFromList: false,
  },
  compactBlur: {
    type: "number",
    min: 0,
    max: 40,
    step: 1,
    default: 12,
    description: "Blur after the cut",
    hiddenFromList: false,
  },
  gradientStart: {
    type: "color",
    default: "#f04a14",
    description: "Gradient start",
  },
  gradientEnd: {
    type: "color",
    default: "#f3f1f1",
    description: "Gradient end",
  },
  ghostColor: {
    type: "color",
    default: "#170b0a",
    description: "Unrevealed text color",
  },
  backgroundColor: {
    type: "color",
    default: "#000000",
    description: "Background color",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","giantFontSize","compactFontSize","anchorOffsetX","giantTravel","settleTravel","cutFrame","revealSoftness","compactBlur","gradientStart","gradientEnd","ghostColor","backgroundColor","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Introducing",
  giantFontSize: 520,
  compactFontSize: 132,
  anchorOffsetX: -16,
  giantTravel: 400,
  settleTravel: 160,
  cutFrame: 13,
  revealSoftness: 14,
  compactBlur: 12,
  gradientStart: "#f04a14",
  gradientEnd: "#f3f1f1",
  ghostColor: "#170b0a",
  backgroundColor: "#000000",
  fontWeight: "700",
  speed: 1,
};

type GradientScaleCutTextElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GradientScaleCutTextBase>;

const GradientScaleCutTextInner = forwardRef<
  HTMLDivElement,
  GradientScaleCutTextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GradientScaleCutText>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GradientScaleCutTextBase
          {...(componentProps as unknown as ComponentProps<typeof GradientScaleCutTextBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GradientScaleCutText = Interactive.withSchema({
  Component: GradientScaleCutTextInner,
  componentName: "<GradientScaleCutText>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
